// Frase del día en la pantalla de acceso: una distinta cada día del año.
// TODAS llevan autor (lo pidió el dueño: «no me sirve que no tenga autor»). 75 comprobadas en
// Wikiquote (f = su fuente) y 163 aportadas por el dueño (f = «aportada por GastroGoan»).
// Una por día; cuando se acaban, vuelve a empezar.
const FRASES_DIA = [
  {"es": "Nadie nace siendo un gran cocinero; se aprende haciendo.", "ca": "Ningú neix sent un gran cuiner; s'aprèn fent.", "en": "No one is born a great cook; one learns by doing.", "a": "Julia Child", "f": "My Life in France, cap. 3"},
  {"es": "Si quieres convertirte en un gran chef, tienes que trabajar con grandes chefs.", "ca": "Si vols convertir-te en un gran xef, has de treballar amb grans xefs.", "en": "If you want to become a great chef, you have to work with great chefs.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "La calidad empieza en el origen del ingrediente.", "ca": "La qualitat comença a l'origen de l'ingredient.", "en": "Quality starts at the ingredient's origin.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "La rentabilidad necesita planificación.", "ca": "La rendibilitat necessita planificació.", "en": "Profitability needs planning.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Para nosotros, los ingredientes siempre brillan, y el sabor final es siempre lo más importante.", "ca": "Per a nosaltres, els ingredients sempre brillen, i el gust final és sempre el més important.", "en": "In our approach, the ingredients always shine, with the end flavour always the most important goal.", "a": "Elena Reygadas", "f": "en.wikiquote"},
  {"es": "Un chef no puede hacerlo todo solo.", "ca": "Un xef no ho pot fer tot sol.", "en": "A chef can't do everything alone.", "a": "Eric Ripert", "f": "aportada por GastroGoan"},
  {"es": "La cocina requiere tanto conocimiento como sensibilidad.", "ca": "La cuina requereix tant coneixement com sensibilitat.", "en": "Cooking requires as much knowledge as sensitivity.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "La cocina puede cuestionar lo que creemos saber sobre los alimentos.", "ca": "La cuina pot qüestionar el que creiem saber sobre els aliments.", "en": "Cooking can question what we think we know about food.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "El descubrimiento de un plato nuevo hace más por la felicidad del género humano que el descubrimiento de una estrella.", "ca": "El descobriment d'un plat nou fa més per la felicitat del gènere humà que el descobriment d'una estrella.", "en": "The discovery of a new dish does more for the happiness of mankind than the discovery of a star.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "Toda mi carrera se ha basado en preguntarme el porqué de las cosas.", "ca": "Tota la meva carrera s'ha basat a preguntar-me el perquè de les coses.", "en": "My whole career has been based on asking myself why things are the way they are.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Planificar un buen menú exige experiencia, ciertos conocimientos y mucha reflexión.", "ca": "Planificar un bon menú exigeix experiència, certs coneixements i molta reflexió.", "en": "Planning a good menu demands experience, a certain amount of knowledge and a good deal of thought.", "a": "Fuchsia Dunlop", "f": "Invitation to a Banquet (2023)"},
  {"es": "Un plato puede ser una idea, un recuerdo y una emoción.", "ca": "Un plat pot ser una idea, un record i una emoció.", "en": "A dish can be an idea, a memory and an emotion.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La profesión permite expresar quién eres a través de la comida.", "ca": "La professió permet expressar qui ets a través del menjar.", "en": "The profession lets you express who you are through food.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "La comida está hecha para nutrir el cuerpo y ayudar a la mente. Es una forma de devolver al ser humano a la naturaleza.", "ca": "El menjar està fet per nodrir el cos i ajudar la ment. És una manera de retornar l'ésser humà a la natura.", "en": "Food is meant to nourish your body and help your mind. It is a way of bringing people back to nature.", "a": "Jeong Kwan", "f": "it.wikiquote"},
  {"es": "El compromiso se demuestra con el trabajo.", "ca": "El compromís es demostra amb la feina.", "en": "Commitment is shown through work.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "La pasión, la ilusión y la obsesión están detrás de los niveles más altos de creatividad.", "ca": "La passió, la il·lusió i l'obsessió són darrere dels nivells més alts de creativitat.", "en": "Passion, enthusiasm and obsession lie behind the highest levels of creativity.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "El trabajo de un chef es ofrecer una visión del mundo a través de la comida.", "ca": "La feina d'un xef és oferir una visió del món a través del menjar.", "en": "A chef's job is to offer a vision of the world through food.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "Compartir una comida permite conocer mejor a alguien.", "ca": "Compartir un àpat permet conèixer millor algú.", "en": "Sharing a meal lets you get to know someone better.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "Invitar a alguien es encargarse de su felicidad mientras esté bajo nuestro techo.", "ca": "Convidar algú és fer-se càrrec de la seva felicitat mentre sigui sota el nostre sostre.", "en": "To invite someone is to take charge of their happiness for as long as they are under our roof.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "Una cocina profesional necesita disciplina.", "ca": "Una cuina professional necessita disciplina.", "en": "A professional kitchen needs discipline.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "He visto que cocinar es una forma de dar amor y cariño, y de expresarnos.", "ca": "He vist que cuinar és una manera de donar amor i afecte, i d'expressar-nos.", "en": "I've seen that cooking is a way of giving love and affection and expressing ourselves.", "a": "Elena Reygadas", "f": "Entrevista, mejor chef del mundo 2023"},
  {"es": "La cocina es una combinación de técnica, creatividad y cultura.", "ca": "La cuina és una combinació de tècnica, creativitat i cultura.", "en": "Cooking is a combination of technique, creativity and culture.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Un buen jefe enseña y devuelve a su equipo lo que exige de él.", "ca": "Un bon cap ensenya i retorna al seu equip el que n'exigeix.", "en": "A good boss teaches and gives back to the team what he demands of it.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "Si dominas una técnica, apenas necesitas volver a mirar una receta.", "ca": "Si domines una tècnica, gairebé no et cal tornar a mirar una recepta.", "en": "Once you've mastered a technique, you barely need to look at a recipe again.", "a": "Julia Child", "f": "aportada por GastroGoan"},
  {"es": "Transformar lo que se pasa por alto en algo extraordinario cambia nuestra percepción.", "ca": "Transformar el que es passa per alt en una cosa extraordinària canvia la nostra percepció.", "en": "Turning the overlooked into something extraordinary changes how we see things.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La innovación de hoy es la tradición de mañana.", "ca": "La innovació d'avui és la tradició de demà.", "en": "Today's innovation is tomorrow's tradition.", "a": "Lidia Bastianich", "f": "aportada por GastroGoan"},
  {"es": "La cocina es humanidad, colaboración y cooperación.", "ca": "La cuina és humanitat, col·laboració i cooperació.", "en": "Cooking is humanity, collaboration and cooperation.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "Quiero probar platos con carácter y sabores decididos.", "ca": "Vull tastar plats amb caràcter i gustos decidits.", "en": "I want to taste dishes with character and bold flavours.", "a": "Joe Bastianich", "f": "MasterChef Italia"},
  {"es": "El destino de las naciones depende de la manera en que se alimentan.", "ca": "El destí de les nacions depèn de la manera com s'alimenten.", "en": "The destiny of nations depends on the manner in which they are fed.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "La comida perfecta es la ósmosis entre aroma, sabor, servicio, decoración, vajilla, lugar y las personas que comparten el momento contigo.", "ca": "El menjar perfecte és l'osmosi entre aroma, gust, servei, decoració, vaixella, lloc i les persones que comparteixen el moment amb tu.", "en": "The perfect meal is the osmosis between aroma, taste, service, design, tableware, place and the people who share the moment with you.", "a": "Anne-Sophie Pic", "f": "en.wikiquote"},
  {"es": "La experiencia gastronómica va más allá del sabor.", "ca": "L'experiència gastronòmica va més enllà del gust.", "en": "The dining experience goes beyond flavour.", "a": "Heston Blumenthal", "f": "aportada por GastroGoan"},
  {"es": "A todos les gusta pensar que los cocineros cuidamos, pero quizá solo controlamos: controlamos lo que come la gente.", "ca": "A tothom li agrada pensar que els cuiners cuidem, però potser només controlem: controlem el que menja la gent.", "en": "Everybody likes to think cooks are nurturing, but maybe we're just controlling what people eat.", "a": "Nigella Lawson", "f": "Entrevista (2020-2021)"},
  {"es": "La técnica debe ser consistente para que la creatividad funcione.", "ca": "La tècnica ha de ser constant perquè la creativitat funcioni.", "en": "Technique must be consistent for creativity to work.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La memoria puede convertirse en un ingrediente creativo.", "ca": "La memòria es pot convertir en un ingredient creatiu.", "en": "Memory can become a creative ingredient.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La comida perfecta ocurre en un contexto que muchas veces tiene muy poco que ver con la comida en sí.", "ca": "El menjar perfecte passa en un context que moltes vegades té molt poc a veure amb el menjar en si.", "en": "The perfect meal, or the best meals, occur in a context that frequently has very little to do with the food itself.", "a": "Anthony Bourdain", "f": "Entrevista con Alden Mudge"},
  {"es": "La cocina creativa consiste en cambiar la manera de mirar las cosas.", "ca": "La cuina creativa consisteix a canviar la manera de mirar les coses.", "en": "Creative cooking is about changing the way you look at things.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La mesa es el único lugar donde nadie se aburre durante la primera hora.", "ca": "La taula és l'únic lloc on ningú s'avorreix durant la primera hora.", "en": "The table is the only place where one is never bored during the first hour.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "La cocina debe estar conectada con la tierra.", "ca": "La cuina ha d'estar connectada amb la terra.", "en": "Cooking must be connected to the land.", "a": "Alice Waters", "f": "aportada por GastroGoan"},
  {"es": "El plan de negocio es parte de la idea gastronómica.", "ca": "El pla de negoci és part de la idea gastronòmica.", "en": "The business plan is part of the culinary idea.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Los chefs somos un poco como entrenadores: primero hay que conocer a cada uno para que el equipo funcione lo mejor posible.", "ca": "Els xefs som una mica com entrenadors: primer cal conèixer cadascú perquè l'equip funcioni al màxim.", "en": "Chefs are a bit like coaches: first you must know each person to get the best out of the team.", "a": "Antonino Cannavacciuolo", "f": "it.wikiquote"},
  {"es": "Aprender a cocinar exige observar, probar y corregir.", "ca": "Aprendre a cuinar exigeix observar, tastar i corregir.", "en": "Learning to cook demands watching, tasting and correcting.", "a": "Jacques Pépin", "f": "aportada por GastroGoan"},
  {"es": "El reto es conseguir que la cocina se tome en serio.", "ca": "El repte és aconseguir que la cuina es prengui seriosament.", "en": "The challenge is getting cooking taken seriously.", "a": "Joan Roca", "f": "ca.wikiquote (2014)"},
  {"es": "El talento necesita trabajo para desarrollarse.", "ca": "El talent necessita feina per desenvolupar-se.", "en": "Talent needs work to develop.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "El chef está para liderar al equipo, no solo para dirigir la cocina.", "ca": "El xef hi és per liderar l'equip, no només per dirigir la cuina.", "en": "A chef is there to lead the team, not just to run the kitchen.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "Ser un gran chef hoy no es suficiente: también hay que ser un gran empresario.", "ca": "Avui ser un gran xef no és suficient: també cal ser un gran empresari.", "en": "Being a great chef isn't enough today; you also have to be a great businessperson.", "a": "Wolfgang Puck", "f": "aportada por GastroGoan"},
  {"es": "La gastronomía tiene una responsabilidad cultural.", "ca": "La gastronomia té una responsabilitat cultural.", "en": "Gastronomy has a cultural responsibility.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "El problema de la cocina moderna es que deja al cocinero en un estado de eficiencia al límite: todo prisa y poco placer.", "ca": "El problema de la cuina moderna és que deixa el cuiner en un estat d'eficiència al límit: tot pressa i poc plaer.", "en": "The trouble with modern cooking is the mood it induces in the cook: skin-of-the-teeth efficiency, all briskness and little pleasure.", "a": "Nigella Lawson", "f": "How to Be a Domestic Goddess (2000)"},
  {"es": "La sostenibilidad empieza por aprovechar lo que tenemos.", "ca": "La sostenibilitat comença per aprofitar el que tenim.", "en": "Sustainability starts with making the most of what we have.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La eficiencia es importante en un negocio competitivo.", "ca": "L'eficiència és important en un negoci competitiu.", "en": "Efficiency matters in a competitive business.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La tradición italiana se basa en utilizarlo todo: no se tira nada.", "ca": "La tradició italiana es basa a aprofitar-ho tot: no es llença res.", "en": "Italian tradition is based on using everything: nothing is thrown away.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La comida forma parte de nuestra identidad.", "ca": "El menjar forma part de la nostra identitat.", "en": "Food is part of our identity.", "a": "José Andrés", "f": "aportada por GastroGoan"},
  {"es": "Cuando nada se desperdicia, todo se vuelve posible.", "ca": "Quan res no es malbarata, tot esdevé possible.", "en": "When nothing is wasted, everything becomes possible.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "Espero que todos mis platos estén equilibrados. Quiero que la gente, y su estómago, se sientan bien cuando comen mi comida.", "ca": "Espero que tots els meus plats siguin equilibrats. Vull que la gent, i el seu estómac, se sentin bé quan mengen el meu menjar.", "en": "My hope is that all my dishes are balanced. I want people, and their stomachs, to feel good when they eat my food.", "a": "Elena Reygadas", "f": "«Inside the Kitchen of Elena Reygadas»"},
  {"es": "Este es un dulce que quiere verte la cara: para que salga bien pide paciencia y atención.", "ca": "Aquest és un dolç que et vol veure la cara: perquè surti bé demana paciència i atenció.", "en": "This is a sweet that wants to look you in the face: to turn out well it asks for patience and attention.", "a": "Pellegrino Artusi", "f": "La scienza in cucina e l'arte di mangiar bene (1891)"},
  {"es": "La tradición puede ser un punto de partida para crear.", "ca": "La tradició pot ser un punt de partida per crear.", "en": "Tradition can be a starting point for creating.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La cocina creativa también necesita un modelo de negocio.", "ca": "La cuina creativa també necessita un model de negoci.", "en": "Creative cooking also needs a business model.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Cocinero se hace uno; asador se nace.", "ca": "Cuiner, s'hi fa; rostidor, s'hi neix.", "en": "One becomes a cook, but one is born a roaster.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "Un restaurante se mide por sus estrellas Michelin; en cambio, el éxito de un libro de cocina se mide por las manchas que tiene.", "ca": "Un restaurant es mesura per les estrelles Michelin; en canvi, els èxits d'un llibre de cuina es mesuren per les taques que té.", "en": "A restaurant is measured by its Michelin stars; a cookbook's success, by its stains.", "a": "Ada Parellada", "f": "Primer cal batre els ous... (2010)"},
  {"es": "La gestión y la calidad son claves para mejorar un negocio gastronómico.", "ca": "La gestió i la qualitat són claus per millorar un negoci gastronòmic.", "en": "Management and quality are key to improving a food business.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Dime lo que comes y te diré lo que eres.", "ca": "Digues-me què menges i et diré què ets.", "en": "Tell me what you eat, and I will tell you what you are.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "La experiencia de comer depende también del momento y de la compañía.", "ca": "L'experiència de menjar depèn també del moment i de la companyia.", "en": "The experience of eating also depends on the moment and the company.", "a": "Heston Blumenthal", "f": "aportada por GastroGoan"},
  {"es": "Los restaurantes son de los negocios más complejos a nivel sistémico.", "ca": "Els restaurants són dels negocis més complexos a nivell sistèmic.", "en": "Restaurants are among the most systemically complex businesses.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La cualidad más indispensable del cocinero es la puntualidad; también debe serlo la del invitado.", "ca": "La qualitat més indispensable del cuiner és la puntualitat; també ho ha de ser la del convidat.", "en": "The most indispensable quality of a cook is punctuality; it should also be that of the guest.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "La estacionalidad es una manera de cocinar con sentido.", "ca": "L'estacionalitat és una manera de cuinar amb sentit.", "en": "Seasonality is a way of cooking with purpose.", "a": "Dan Barber", "f": "aportada por GastroGoan"},
  {"es": "La cocina forma caracteres fuertes.", "ca": "La cuina forma caràcters forts.", "en": "The kitchen builds strong characters.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "Hay que aprender a levantarse después de los fracasos.", "ca": "Cal aprendre a aixecar-se després dels fracassos.", "en": "You have to learn to get back up after failure.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "Un postre sin queso es una belleza a la que le falta un ojo.", "ca": "Unes postres sense formatge són una bellesa a qui falta un ull.", "en": "A dessert without cheese is a beauty with only one eye.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "La innovación también consiste en encontrar posibilidades donde otros no las ven.", "ca": "La innovació també consisteix a trobar possibilitats on els altres no en veuen.", "en": "Innovation is also about finding possibilities where others don't see them.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "Una onza de salsa tapa una multitud de pecados.", "ca": "Una unça de salsa tapa una multitud de pecats.", "en": "An ounce of sauce covers a multitude of sins.", "a": "Anthony Bourdain", "f": "Kitchen Confidential (2000)"},
  {"es": "La carta se basa en el calendario y en los ingredientes que nos da la naturaleza.", "ca": "La carta es basa en el calendari i en els ingredients que ens dona la natura.", "en": "The menu is based on the timeline and the ingredients that nature gives us.", "a": "Elena Reygadas", "f": "en.wikiquote"},
  {"es": "El trabajo bien hecho requiere concentración.", "ca": "La feina ben feta requereix concentració.", "en": "Work done well requires concentration.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La cocina es una forma de comprender el mundo.", "ca": "La cuina és una manera de comprendre el món.", "en": "Cooking is a way of understanding the world.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "Claro que sienta muy bien un premio, pero una cocina es un universo.", "ca": "És clar que un premi fa molta il·lusió, però una cuina és un univers.", "en": "Of course, it feels great to be awarded, but a kitchen is a universe.", "a": "Elena Reygadas", "f": "en.wikiquote"},
  {"es": "Si queremos saber si un libro ha sido «cocinado», es decir, si le ha servido a quien lo compró, hay que mirar si tiene el índice lleno de manchas de grasa.", "ca": "Si volem saber si un llibre ha estat «cuinat», és a dir, si ha fet servei al comprador, hem de mirar si té un índex llardós.", "en": "To know whether a cookbook has truly been used, look for a greasy index.", "a": "Ada Parellada", "f": "Primer cal batre els ous... (2010)"},
  {"es": "Los estándares deben sostenerse incluso bajo presión.", "ca": "Els estàndards s'han de mantenir fins i tot sota pressió.", "en": "Standards must hold even under pressure.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "La consistencia es una parte esencial de la cocina profesional.", "ca": "La constància és una part essencial de la cuina professional.", "en": "Consistency is an essential part of professional cooking.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "La sostenibilidad empieza por cómo compramos y utilizamos los alimentos.", "ca": "La sostenibilitat comença per com comprem i fem servir els aliments.", "en": "Sustainability starts with how we buy and use food.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "Mi objetivo número uno siempre ha sido hacer felices a nuestros clientes con comida sencilla basada en ingredientes mexicanos.", "ca": "El meu objectiu número u sempre ha estat fer feliços els nostres clients amb menjar senzill basat en ingredients mexicans.", "en": "My number one goal has always been to make our guests happy by offering them simple food based in Mexican ingredients.", "a": "Elena Reygadas", "f": "en.wikiquote"},
  {"es": "Tuve mucha suerte de que mi padre y mi madre me enseñaran que no comemos solo para vivir, sino también por placer.", "ca": "Vaig tenir molta sort que el meu pare i la meva mare m'ensenyessin que no mengem només per viure, sinó també per plaer.", "en": "I was very lucky that my father and my mother told me that we eat not only to live but also for pleasure.", "a": "Anne-Sophie Pic", "f": "en.wikiquote"},
  {"es": "La cocina debe respetar el producto.", "ca": "La cuina ha de respectar el producte.", "en": "Cooking must respect the ingredient.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "No me demostraba su cariño con abrazos ni grandes palabras, sino con comida y cuidados.", "ca": "No em demostrava el seu afecte amb abraçades ni grans paraules, sinó amb menjar i atencions.", "en": "She didn't show her love for me by hugging, but through food and fussing.", "a": "Fuchsia Dunlop", "f": "Invitation to a Banquet (2023)"},
  {"es": "Cocinar es como componer música: una vez escrita, cada uno la interpreta con su sensibilidad.", "ca": "Cuinar és com compondre música: un cop escrita, cadascú la interpreta amb la seva sensibilitat.", "en": "Cooking is like composing music: once it's written, everyone performs it with their own sensibility.", "a": "Carlo Cracco", "f": "it.wikiquote"},
  {"es": "«Demasiado trabajo», «demasiado caro» o «quién va a notar la diferencia» son la sentencia de muerte de la buena comida.", "ca": "«Massa feina», «massa car» o «qui notarà la diferència» són la sentència de mort del bon menjar.", "en": "\"Too much trouble\", \"too expensive\" or \"who will know the difference\" are death knells for good food.", "a": "Julia Child", "f": "Mastering the Art of French Cooking, prólogo (1961)"},
  {"es": "A veces se abre un restaurante con pasión, pero sin un plan de empresa sólido.", "ca": "De vegades s'obre un restaurant amb passió, però sense un pla d'empresa sòlid.", "en": "Sometimes a restaurant opens with passion but without a solid business plan.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "El universo no es nada sin la vida, y todo lo que vive se alimenta.", "ca": "L'univers no és res sense la vida, i tot el que viu s'alimenta.", "en": "The universe is nothing without life, and all that lives must eat.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "El control y la revisión constante ayudan a mejorar la eficiencia.", "ca": "El control i la revisió constant ajuden a millorar l'eficiència.", "en": "Control and constant review help improve efficiency.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Voy de caos en caos; cocinar es lo más ordenado que hago.", "ca": "Vaig de caos en caos; cuinar és el més endreçat que faig.", "en": "I lurch from chaos to chaos — cooking is the neatest thing I do.", "a": "Nigella Lawson", "f": "Entrevista con Jane Warren"},
  {"es": "La organización no está reñida con la creatividad.", "ca": "L'organització no està renyida amb la creativitat.", "en": "Organisation is not at odds with creativity.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Es más fácil ser amable que ser desagradable.", "ca": "És més fàcil ser amable que ser desagradable.", "en": "It's easier to be nice than to be nasty.", "a": "Wolfgang Puck", "f": "aportada por GastroGoan"},
  {"es": "La gastronomía también tiene una responsabilidad social.", "ca": "La gastronomia també té una responsabilitat social.", "en": "Gastronomy also has a social responsibility.", "a": "José Andrés", "f": "aportada por GastroGoan"},
  {"es": "Me gusta que la gente sepa disfrutar no solo con la boca y no enseguida: antes están los olores, antes está el aspecto del plato.", "ca": "M'agrada que la gent sàpiga gaudir no només amb la boca i no de seguida: abans hi ha les olors, abans hi ha l'aspecte del plat.", "en": "I like people to taste not only with their mouths and not straight away: first come the smells, first comes the look of the dish.", "a": "Carlo Cracco", "f": "it.wikiquote"},
  {"es": "Un restaurante necesita una idea clara de lo que quiere ser.", "ca": "Un restaurant necessita una idea clara del que vol ser.", "en": "A restaurant needs a clear idea of what it wants to be.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Un equipo funciona cuando todos entienden su papel.", "ca": "Un equip funciona quan tothom entén el seu paper.", "en": "A team works when everyone understands their role.", "a": "Eric Ripert", "f": "aportada por GastroGoan"},
  {"es": "Un buen cocinero necesita conocer sus ingredientes.", "ca": "Un bon cuiner necessita conèixer els seus ingredients.", "en": "A good cook needs to know their ingredients.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "El liderazgo exige saber comunicar.", "ca": "El lideratge exigeix saber comunicar.", "en": "Leadership demands knowing how to communicate.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "La cocina está conectada con la memoria.", "ca": "La cuina està connectada amb la memòria.", "en": "Cooking is connected to memory.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La precisión importa tanto como la creatividad.", "ca": "La precisió importa tant com la creativitat.", "en": "Precision matters as much as creativity.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "Tienes talento cuando hablan bien de ti durante muchos años.", "ca": "Tens talent quan parlen bé de tu durant molts anys.", "en": "You have talent when people speak well of you for many years.", "a": "Carlo Cracco", "f": "it.wikiquote"},
  {"es": "La cocina puede aportar dignidad a quienes la necesitan.", "ca": "La cuina pot aportar dignitat als qui la necessiten.", "en": "Cooking can bring dignity to those who need it.", "a": "José Andrés", "f": "aportada por GastroGoan"},
  {"es": "Para alcanzar un nivel extraordinario hacen falta esfuerzo y constancia.", "ca": "Per arribar a un nivell extraordinari calen esforç i constància.", "en": "Reaching an extraordinary level takes effort and perseverance.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Quien recibe a sus amigos y no cuida personalmente la comida que se les prepara no es digno de tener amigos.", "ca": "Qui rep els seus amics i no té cura personalment del menjar que se'ls prepara no és digne de tenir amics.", "en": "Whoever receives friends and gives no personal care to the meal prepared for them is not worthy of having friends.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "La cocina vegetal tiene todos los colores del huerto. Nos hace redescubrir sabores antiguos y nos devuelve al ritmo de las estaciones.", "ca": "La cuina vegetal té tots els colors de l'hort. Ens fa redescobrir gustos antics i ens retorna al ritme de les estacions.", "en": "Vegetable cooking has all the colours of the garden. It brings back old flavours and puts us in tune with the seasons.", "a": "Antonino Cannavacciuolo", "f": "it.wikiquote"},
  {"es": "La mala educación no es «divertirse»; y si lo es, es a costa de otra persona.", "ca": "La mala educació no és «divertir-se»; i si ho és, és a costa d'una altra persona.", "en": "Rudeness is not \"having fun\", and if it is, it's at the expense of another person.", "a": "Marco Pierre White", "f": "Entrevista en Triple M (2013)"},
  {"es": "La sorpresa es una parte esencial de la experiencia gastronómica.", "ca": "La sorpresa és una part essencial de l'experiència gastronòmica.", "en": "Surprise is an essential part of the dining experience.", "a": "Heston Blumenthal", "f": "aportada por GastroGoan"},
  {"es": "Miramos una coliflor y no sabemos qué hacer con ella.", "ca": "Mirem una coliflor i no sabem què fer-ne.", "en": "We look at a cauliflower and don't know what to do with it.", "a": "Ada Parellada", "f": "Entrevista en la revista Rol (2013)"},
  {"es": "Mis mejores clientes no son ricos, sino personas que una o dos veces al año deciden gastarse en una cena lo que en unos zapatos. Y el recuerdo dura años.", "ca": "Els meus millors clients no són rics, sinó persones que un o dos cops l'any decideixen gastar-se en un sopar el que en unes sabates. I el record dura anys.", "en": "My best customers aren't rich, but people who once or twice a year spend on a dinner what they'd spend on shoes. And the memory lasts for years.", "a": "Carlo Cracco", "f": "it.wikiquote"},
  {"es": "La cocina debe respetar la naturaleza y a quienes producen los alimentos.", "ca": "La cuina ha de respectar la natura i els qui produeixen els aliments.", "en": "Cooking must respect nature and those who produce our food.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "Fue la cocina la que me eligió a mí. Me abrió una puerta y yo entré.", "ca": "Va ser la cuina qui em va triar a mi. Em va obrir una porta i jo hi vaig entrar.", "en": "Cooking chose me. It opened a door and I walked through it.", "a": "Massimo Bottura", "f": "it.wikiquote"},
  {"es": "Las técnicas no son lo más difícil de enseñar; las actitudes importan mucho más.", "ca": "Les tècniques no són el més difícil d'ensenyar; les actituds importen molt més.", "en": "Techniques aren't the hardest thing to teach; attitudes matter far more.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "Los alimentos cuentan la historia de un territorio.", "ca": "Els aliments expliquen la història d'un territori.", "en": "Food tells the story of a place.", "a": "René Redzepi", "f": "aportada por GastroGoan"},
  {"es": "El mejor maestro es la práctica junto a alguien que sabe del oficio.", "ca": "El millor mestre és la pràctica al costat d'algú que en sap, de l'ofici.", "en": "The best teacher is practice under a capable master.", "a": "Pellegrino Artusi", "f": "La scienza in cucina e l'arte di mangiar bene (1891)"},
  {"es": "A los cuarenta años supe que mi objetivo sería cocinar con sencillez, según el precepto de que la materia es forma.", "ca": "Als quaranta anys vaig saber que el meu objectiu seria cuinar amb senzillesa, segons el precepte que la matèria és forma.", "en": "At forty I knew my goal would be to cook with simplicity, following the precept that matter is form.", "a": "Gualtiero Marchesi", "f": "it.wikiquote"},
  {"es": "La calidad debe mantenerse servicio tras servicio.", "ca": "La qualitat s'ha de mantenir servei rere servei.", "en": "Quality must be maintained service after service.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "No basta con hacer algo diferente; tiene que tener sentido.", "ca": "No n'hi ha prou de fer una cosa diferent; ha de tenir sentit.", "en": "Doing something different isn't enough; it has to make sense.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Todos necesitan un mentor.", "ca": "Tothom necessita un mentor.", "en": "Everybody needs a mentor.", "a": "Emeril Lagasse", "f": "aportada por GastroGoan"},
  {"es": "La creatividad debe convertirse en una experiencia que el cliente valore.", "ca": "La creativitat s'ha de convertir en una experiència que el client valori.", "en": "Creativity must become an experience the guest values.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Quienes se indigestan o se emborrachan no saben ni beber ni comer.", "ca": "Els qui s'empatxen o s'emborratxen no saben ni beure ni menjar.", "en": "Those who give themselves indigestion or get drunk know neither how to eat nor how to drink.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826), aforismos"},
  {"es": "Cocinar es una forma de decir te quiero.", "ca": "Cuinar és una manera de dir t'estimo.", "en": "Cooking is a way of saying I love you.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La creatividad debe convivir con la viabilidad económica.", "ca": "La creativitat ha de conviure amb la viabilitat econòmica.", "en": "Creativity must coexist with economic viability.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La diversidad enriquece la forma de entender la cocina.", "ca": "La diversitat enriqueix la manera d'entendre la cuina.", "en": "Diversity enriches the way we understand cooking.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La innovación no garantiza el éxito de un restaurante.", "ca": "La innovació no garanteix l'èxit d'un restaurant.", "en": "Innovation doesn't guarantee a restaurant's success.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La comida puede ser una fuerza para el bien.", "ca": "El menjar pot ser una força per al bé.", "en": "Food can be a force for good.", "a": "José Andrés", "f": "aportada por GastroGoan"},
  {"es": "La generosidad es una parte importante de la profesión.", "ca": "La generositat és una part important de la professió.", "en": "Generosity is an important part of the profession.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La gastronomía es el conocimiento razonado de todo lo que tiene que ver con el hombre en cuanto se alimenta.", "ca": "La gastronomia és el coneixement raonat de tot el que té a veure amb l'home en tant que s'alimenta.", "en": "Gastronomy is the reasoned knowledge of everything that relates to man as he eats.", "a": "Jean Anthelme Brillat-Savarin", "f": "Fisiología del gusto (1826)"},
  {"es": "Los cocineros pueden contribuir a mejorar el sistema alimentario.", "ca": "Els cuiners poden contribuir a millorar el sistema alimentari.", "en": "Cooks can help improve the food system.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La creatividad requiere curiosidad.", "ca": "La creativitat requereix curiositat.", "en": "Creativity requires curiosity.", "a": "Heston Blumenthal", "f": "aportada por GastroGoan"},
  {"es": "La cocina refleja la cultura de quienes la practican.", "ca": "La cuina reflecteix la cultura dels qui la practiquen.", "en": "Cooking reflects the culture of those who practise it.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "Hay que ser un romántico para invertir tu tiempo, tu dinero y tu vida en el queso.", "ca": "Cal ser un romàntic per invertir el teu temps, els teus diners i la teva vida en el formatge.", "en": "You have to be a romantic to invest yourself, your money, and your time in cheese.", "a": "Anthony Bourdain", "f": "Medium Raw (2010)"},
  {"es": "La gastronomía puede acercar a personas distintas.", "ca": "La gastronomia pot apropar persones diferents.", "en": "Gastronomy can bring different people together.", "a": "José Andrés", "f": "aportada por GastroGoan"},
  {"es": "El mundo, hipócrita, no quiere darle importancia a la comida; pero luego no hay fiesta en la que no se tienda el mantel y se busque comer lo mejor.", "ca": "El món, hipòcrita, no vol donar importància al menjar; però després no hi ha festa en què no s'estengui les estovalles i es busqui menjar el millor.", "en": "The hypocritical world won't admit that eating matters; yet there's no celebration without a tablecloth and the best food we can find.", "a": "Pellegrino Artusi", "f": "La scienza in cucina e l'arte di mangiar bene (1891)"},
  {"es": "La creatividad es fácil; lo difícil es tener la idea.", "ca": "La creativitat és fàcil; el difícil és tenir la idea.", "en": "Creativity is easy; the hard part is having the idea.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "No basta con saber hacer un escalope para abrir un restaurante. Hay que saber construir un equipo, y mantenerlo.", "ca": "No n'hi ha prou de saber fer un escalopa per obrir un restaurant. Cal saber construir un equip, i mantenir-lo.", "en": "Knowing how to make an escalope isn't enough to open a restaurant. You have to know how to build a team, and keep it.", "a": "Antonino Cannavacciuolo", "f": "it.wikiquote"},
  {"es": "La cocina profesional requiere consistencia, no solo inspiración.", "ca": "La cuina professional requereix constància, no només inspiració.", "en": "Professional cooking requires consistency, not just inspiration.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "La excelencia exige práctica.", "ca": "L'excel·lència exigeix pràctica.", "en": "Excellence demands practice.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La cocina de aprovechamiento es una forma de creatividad.", "ca": "La cuina d'aprofitament és una forma de creativitat.", "en": "Cooking with leftovers is a form of creativity.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "No eres siempre la persona más importante ni la más inteligente de la sala.", "ca": "No sempre ets la persona més important ni la més intel·ligent de la sala.", "en": "You're not always the most important or the smartest person in the room.", "a": "Mario Batali", "f": "aportada por GastroGoan"},
  {"es": "La cocina es una forma de expresión.", "ca": "La cuina és una forma d'expressió.", "en": "Cooking is a form of expression.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Cuando cocinas, debería ser un acto de amor.", "ca": "Quan cuines, hauria de ser un acte d'amor.", "en": "When you cook it should be an act of love.", "a": "Raymond Blanc", "f": "Entrevista en The Times"},
  {"es": "La cocina profesional es mucho más que elaborar recetas.", "ca": "La cuina professional és molt més que elaborar receptes.", "en": "Professional cooking is much more than following recipes.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "Un buen plato puede transformar un ingrediente sencillo.", "ca": "Un bon plat pot transformar un ingredient senzill.", "en": "A good dish can transform a simple ingredient.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La cocina se aprende trabajando.", "ca": "La cuina s'aprèn treballant.", "en": "Cooking is learned by working.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "No soporto a la gente que maltrata al personal de sala. De hecho, me parece intolerable.", "ca": "No suporto la gent que maltracta el personal de sala. De fet, em sembla intolerable.", "en": "I am not a fan of people who abuse service staff. In fact, I find it intolerable.", "a": "Anthony Bourdain", "f": "Medium Raw (2010)"},
  {"es": "Mi cocina es muy delicada y soy una perfeccionista total: las herramientas se vuelven una extensión de mi mano.", "ca": "La meva cuina és molt delicada i sóc una perfeccionista total: les eines esdevenen una extensió de la meva mà.", "en": "My cuisine is very delicate and I'm a complete perfectionist, so these tools become an extension of my hand.", "a": "Anne-Sophie Pic", "f": "«60 Seconds With… Anne-Sophie Pic», Guía Michelin"},
  {"es": "Un cocinero debe ser, más que nunca, libre para crear.", "ca": "Un cuiner ha de ser, més que mai, lliure per crear.", "en": "A cook must be, more than ever, free to create.", "a": "Gualtiero Marchesi", "f": "it.wikiquote"},
  {"es": "Trabaja duro y no pierdas de vista lo que quieres conseguir.", "ca": "Treballa dur i no perdis de vista el que vols aconseguir.", "en": "Work hard and never lose sight of what you want to achieve.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "La atención al detalle marca la diferencia.", "ca": "L'atenció al detall marca la diferència.", "en": "Attention to detail makes the difference.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La cocina es una profesión exigente.", "ca": "La cuina és una professió exigent.", "en": "Cooking is a demanding profession.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "La disciplina es necesaria para dominar un oficio.", "ca": "La disciplina és necessària per dominar un ofici.", "en": "Discipline is necessary to master a craft.", "a": "Jiro Ono", "f": "aportada por GastroGoan"},
  {"es": "El producto final refleja las decisiones que se han tomado antes.", "ca": "El producte final reflecteix les decisions que s'han pres abans.", "en": "The final product reflects the decisions made beforehand.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "No abro restaurantes, cuento historias.", "ca": "No obro restaurants, explico històries.", "en": "I don't open restaurants; I tell stories.", "a": "José Andrés", "f": "aportada por GastroGoan"},
  {"es": "Intentamos ser puros y respetar al máximo los ingredientes, sin dejar nunca de dar mucho placer.", "ca": "Intentem ser purs i respectar al màxim els ingredients, sense deixar mai de donar molt de plaer.", "en": "We try to be pure and respect the ingredients as much as possible, while always offering loads of pleasure.", "a": "Elena Reygadas", "f": "en.wikiquote"},
  {"es": "Creo que cocinar debería ser diversión y familia.", "ca": "Crec que cuinar hauria de ser diversió i família.", "en": "I think cooking should be about fun and family.", "a": "Nigella Lawson", "f": "Entrevista (2000-2004)"},
  {"es": "La pasión necesita dirección para convertirse en un proyecto viable.", "ca": "La passió necessita direcció per convertir-se en un projecte viable.", "en": "Passion needs direction to become a viable project.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Cocinar es una filosofía, no una receta. Salvo en pastelería: ahí es química.", "ca": "Cuinar és una filosofia, no una recepta. Llevat de la pastisseria: allà és química.", "en": "Cooking is a philosophy, it's not a recipe. Unless it's pastry, then it's chemistry.", "a": "Marco Pierre White", "f": "Entrevista"},
  {"es": "El cocinero profesional repite tareas una y otra vez para garantizar la consistencia.", "ca": "El cuiner professional repeteix tasques una vegada i una altra per garantir la constància.", "en": "A professional cook repeats tasks again and again to guarantee consistency.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "No hay atajos para dominar un oficio.", "ca": "No hi ha dreceres per dominar un ofici.", "en": "There are no shortcuts to mastering a craft.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "La verdadera abundancia también consiste en saber aprovechar los recursos.", "ca": "L'autèntica abundància també consisteix a saber aprofitar els recursos.", "en": "True abundance is also knowing how to make the most of resources.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "No quería que mi fracaso se debiera a una falta de esfuerzo.", "ca": "No volia que el meu fracàs es degués a una falta d'esforç.", "en": "I didn't want my failure to be down to a lack of effort.", "a": "Heston Blumenthal", "f": "aportada por GastroGoan"},
  {"es": "Un plato puede contar una historia sobre el lugar del que procede.", "ca": "Un plat pot explicar una història sobre el lloc d'on prové.", "en": "A dish can tell a story about the place it comes from.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "La cocina es una actividad profundamente humana.", "ca": "La cuina és una activitat profundament humana.", "en": "Cooking is a deeply human activity.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "El exceso de sal es el peor defecto de un plato.", "ca": "L'excés de sal és el pitjor defecte d'un plat.", "en": "Too much salt is the worst flaw a dish can have.", "a": "Pellegrino Artusi", "f": "La scienza in cucina e l'arte di mangiar bene (1891)"},
  {"es": "La gran cocina produce recuerdos duraderos.", "ca": "La gran cuina produeix records duradors.", "en": "Great cooking creates lasting memories.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La creatividad puede ejercerla todo el mundo; el talento creativo es otra cuestión.", "ca": "La creativitat la pot exercir tothom; el talent creatiu és una altra qüestió.", "en": "Anyone can be creative; creative talent is another matter.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La cocina evoluciona cuando se conocen sus raíces.", "ca": "La cuina evoluciona quan se'n coneixen les arrels.", "en": "Cooking evolves when you know its roots.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "El futuro de la gastronomía no consiste en el exceso, sino en crear belleza a través del respeto.", "ca": "El futur de la gastronomia no consisteix en l'excés, sinó a crear bellesa a través del respecte.", "en": "The future of gastronomy isn't excess, but creating beauty through respect.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La comida conecta las tradiciones con el presente.", "ca": "El menjar connecta les tradicions amb el present.", "en": "Food connects traditions with the present.", "a": "Alice Waters", "f": "aportada por GastroGoan"},
  {"es": "Las recetas tradicionales pueden inspirar nuevas ideas.", "ca": "Les receptes tradicionals poden inspirar idees noves.", "en": "Traditional recipes can inspire new ideas.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "De jóvenes, casi todos los cocineros recargan sus platos. Con el tiempo aprenden que la naturaleza es la verdadera artista: nosotros solo somos los cocineros.", "ca": "De joves, gairebé tots els cuiners recarreguen els plats. Amb el temps aprenen que la natura és la veritable artista: nosaltres només som els cuiners.", "en": "Most cooks, when young, overwork their food. In time they learn that Mother Nature is the true artist — we're just the cooks.", "a": "Marco Pierre White", "f": "Marco Pierre White in Hell's Kitchen (2008)"},
  {"es": "La cocina requiere fuerza mental y valentía.", "ca": "La cuina requereix força mental i valentia.", "en": "Cooking requires mental strength and courage.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Un restaurante debe ofrecer algo más que comida.", "ca": "Un restaurant ha d'oferir alguna cosa més que menjar.", "en": "A restaurant must offer more than food.", "a": "Danny Meyer", "f": "aportada por GastroGoan"},
  {"es": "La forma más eficaz de dirigir una cocina es enseñar, no gritar.", "ca": "La manera més eficaç de dirigir una cuina és ensenyar, no cridar.", "en": "The most effective way to run a kitchen is to teach, not to shout.", "a": "Tom Colicchio", "f": "aportada por GastroGoan"},
  {"es": "El desperdicio de alimentos también es desperdicio de recursos y oportunidades.", "ca": "El malbaratament d'aliments també és malbaratament de recursos i d'oportunitats.", "en": "Food waste is also a waste of resources and opportunities.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "Aprende a cocinar: prueba recetas nuevas, aprende de tus errores, no tengas miedo y, sobre todo, ¡diviértete!", "ca": "Aprèn a cuinar: prova receptes noves, aprèn dels teus errors, no tinguis por i, sobretot, diverteix-te!", "en": "Learn how to cook — try new recipes, learn from your mistakes, be fearless, and above all have fun!", "a": "Julia Child", "f": "My Life in France, cap. 9"},
  {"es": "La cocina exige preparación antes de que llegue el cliente.", "ca": "La cuina exigeix preparació abans que arribi el client.", "en": "The kitchen demands preparation before the guest arrives.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "He dedicado mi vida creativa al reto de hacer algo que no se había hecho nunca.", "ca": "He dedicat la meva vida creativa al repte de fer una cosa que no s'havia fet mai.", "en": "I have devoted my creative life to the challenge of doing something that had never been done.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Los ingredientes de temporada son fundamentales para cocinar bien.", "ca": "Els ingredients de temporada són fonamentals per cuinar bé.", "en": "Seasonal ingredients are essential to cooking well.", "a": "Alice Waters", "f": "aportada por GastroGoan"},
  {"es": "La sencillez permite que el producto hable.", "ca": "La senzillesa permet que el producte parli.", "en": "Simplicity lets the ingredient speak.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La técnica se puede enseñar. El carácter, o lo tienes o no lo tienes.", "ca": "La tècnica es pot ensenyar. El caràcter, o el tens o no el tens.", "en": "Skills can be taught. Character you either have or you don't have.", "a": "Anthony Bourdain", "f": "Kitchen Confidential (2000)"},
  {"es": "La tradición no es un límite, es un punto de partida.", "ca": "La tradició no és un límit, és un punt de partida.", "en": "Tradition isn't a limit; it's a starting point.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La cocina debe emocionar, no limitarse a alimentar.", "ca": "La cuina ha d'emocionar, no limitar-se a alimentar.", "en": "Cooking should move people, not just feed them.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "El oficio de cocinero está muy ligado a ser buena persona.", "ca": "L'ofici de cuiner està molt lligat a ser bona persona.", "en": "The cook's trade is closely tied to being a good person.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La gestión permite mejorar los procesos y la eficiencia.", "ca": "La gestió permet millorar els processos i l'eficiència.", "en": "Management improves processes and efficiency.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La excelencia no aparece por casualidad.", "ca": "L'excel·lència no apareix per casualitat.", "en": "Excellence doesn't happen by chance.", "a": "Gordon Ramsay", "f": "aportada por GastroGoan"},
  {"es": "El desperdicio de alimentos no es inevitable.", "ca": "El malbaratament d'aliments no és inevitable.", "en": "Food waste is not inevitable.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La autoridad se construye hablando, respetando al otro y dando siempre ejemplo.", "ca": "L'autoritat es construeix parlant, respectant l'altre i donant sempre exemple.", "en": "Authority is built through discussion, respect for others, and always setting an example.", "a": "Hélène Darroze", "f": "Entrevista con Hélène Darroze"},
  {"es": "La comida nos conecta a todos.", "ca": "El menjar ens connecta a tots.", "en": "Food connects us all.", "a": "Eric Ripert", "f": "aportada por GastroGoan"},
  {"es": "La excelencia exige saber qué quieres conseguir.", "ca": "L'excel·lència exigeix saber què vols aconseguir.", "en": "Excellence demands knowing what you want to achieve.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "Uno de los secretos, y placeres, de la cocina es aprender a corregir lo que sale mal; y una de sus lecciones, aguantar con una sonrisa lo que no tiene arreglo.", "ca": "Un dels secrets, i plaers, de la cuina és aprendre a corregir el que surt malament; i una de les lliçons, aguantar amb un somriure el que no té remei.", "en": "One of the secrets, and pleasures, of cooking is to learn to correct something if it goes awry; and one of the lessons is to grin and bear it if it cannot be fixed.", "a": "Julia Child", "f": "My Life in France, cap. 6"},
  {"es": "La creatividad necesita conocimiento.", "ca": "La creativitat necessita coneixement.", "en": "Creativity needs knowledge.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La repetición correcta crea buenos hábitos.", "ca": "La repetició correcta crea bons hàbits.", "en": "Correct repetition builds good habits.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "La urgencia de ahora es para ayer.", "ca": "La urgència d'ara és per ahir.", "en": "The urgency of now is yesterday.", "a": "José Andrés", "f": "60 Minutes (2020)"},
  {"es": "No se puede montar un restaurante sin educación financiera.", "ca": "No es pot muntar un restaurant sense educació financera.", "en": "You can't open a restaurant without financial literacy.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La creatividad también consiste en saber cuándo no añadir nada más.", "ca": "La creativitat també consisteix a saber quan no afegir-hi res més.", "en": "Creativity is also knowing when not to add anything more.", "a": "Mario Batali", "f": "aportada por GastroGoan"},
  {"es": "La cocina es transformar un producto para alimentarse o disfrutarlo.", "ca": "La cuina és transformar un producte per alimentar-se'n o gaudir-ne.", "en": "Cooking is transforming an ingredient to feed ourselves or to enjoy it.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La cocina es una carrera de aprendizaje constante.", "ca": "La cuina és una carrera d'aprenentatge constant.", "en": "Cooking is a career of constant learning.", "a": "Jacques Pépin", "f": "aportada por GastroGoan"},
  {"es": "Un trozo de pan del día anterior puede convertirse en oro si sabes hacerte las preguntas adecuadas.", "ca": "Un tros de pa del dia anterior pot convertir-se en or si saps fer-te les preguntes adequades.", "en": "A piece of yesterday's bread can become gold if you know how to ask the right questions.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La cocina es un lenguaje con el que expresar ideas.", "ca": "La cuina és un llenguatge amb què expressar idees.", "en": "Cooking is a language for expressing ideas.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Los aromas y los sabores de mi tierra hacen de mí lo que soy.", "ca": "Les aromes i els gustos de la meva terra fan de mi el que sóc.", "en": "The scents and flavours of my land make me who I am.", "a": "Massimo Bottura", "f": "Food for Change"},
  {"es": "La ambición debe ir acompañada de realismo.", "ca": "L'ambició ha d'anar acompanyada de realisme.", "en": "Ambition must go hand in hand with realism.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "La cocina no es moda: la cocina es cultura.", "ca": "La cuina no és moda: la cuina és cultura.", "en": "Cooking is not fashion; cooking is culture.", "a": "Carlo Cracco", "f": "MasterChef Italia"},
  {"es": "La cocina debe evolucionar sin olvidar sus raíces.", "ca": "La cuina ha d'evolucionar sense oblidar les seves arrels.", "en": "Cooking must evolve without forgetting its roots.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "El negocio gastronómico necesita control y organización.", "ca": "El negoci gastronòmic necessita control i organització.", "en": "A food business needs control and organisation.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La cocina no debe ser una competición.", "ca": "La cuina no ha de ser una competició.", "en": "Cooking shouldn't be a competition.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La calidad por sí sola no sustituye una buena gestión.", "ca": "La qualitat per si sola no substitueix una bona gestió.", "en": "Quality alone is no substitute for good management.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "Me enseñaron que la cocina es algo serio y muy preciso. Pero, sobre todo, que la cocina es una fuente de disfrute.", "ca": "Em van ensenyar que la cuina és una cosa seriosa i molt precisa. Però, sobretot, que la cuina és una font de gaudi.", "en": "Growing up, I was taught that cuisine is something serious and very precise. But more than that, that cuisine is a source of enjoyment.", "a": "Anne-Sophie Pic", "f": "Entrevista «I faced the world of cuisine alone»"},
  {"es": "El dominio técnico permite expresar una idea con claridad.", "ca": "El domini tècnic permet expressar una idea amb claredat.", "en": "Technical mastery lets you express an idea clearly.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La perfección son muchas cosas pequeñas bien hechas.", "ca": "La perfecció són moltes coses petites ben fetes.", "en": "Perfection is lots of little things done well.", "a": "Marco Pierre White", "f": "Atribuida por él a Fernand Point"},
  {"es": "Las estrellas son la recompensa al trabajo duro, pero no son el objetivo. El objetivo es hacer disfrutar a los clientes.", "ca": "Les estrelles són la recompensa a la feina dura, però no són l'objectiu. L'objectiu és fer gaudir els clients.", "en": "Stars reward hard work, but they're not the goal. The goal is to give pleasure to the guests.", "a": "Hélène Darroze", "f": "Entrevista «Et si la cuisine était avant tout une affaire de cœur»"},
  {"es": "Si alguien paga mucho dinero por venir a tu restaurante y comer tu comida, tienes el deber de estar en la cocina.", "ca": "Si algú paga molts diners per venir al teu restaurant i menjar el teu menjar, tens el deure de ser a la cuina.", "en": "If someone is paying a lot of money to come to your restaurant and eat your food, you have a duty to be in the kitchen.", "a": "Marco Pierre White", "f": "en.wikiquote"},
  {"es": "Un libro de cocina es tan bueno como su peor receta.", "ca": "Un llibre de cuina és tan bo com la seva pitjor recepta.", "en": "A cookbook is only as good as its worst recipe.", "a": "Julia Child", "f": "Necrológica en The New York Times"},
  {"es": "La actitud de un cocinero es tan importante como su técnica.", "ca": "L'actitud d'un cuiner és tan important com la seva tècnica.", "en": "A cook's attitude is as important as their technique.", "a": "Alain Ducasse", "f": "aportada por GastroGoan"},
  {"es": "Creo que la cocina es el vínculo más importante entre la naturaleza y la cultura.", "ca": "Crec que la cuina és el vincle més important entre la natura i la cultura.", "en": "I believe that cuisine is the most important link between nature and culture.", "a": "Alex Atala", "f": "en.wikiquote"},
  {"es": "Tu arrogancia será el palo en tu propia rueda.", "ca": "La teva arrogància serà el pal a la teva pròpia roda.", "en": "Your arrogance will be the stick in your own wheel.", "a": "Joe Bastianich", "f": "MasterChef Italia"},
  {"es": "La experiencia transforma la técnica en intuición.", "ca": "L'experiència transforma la tècnica en intuïció.", "en": "Experience turns technique into intuition.", "a": "Julia Child", "f": "aportada por GastroGoan"},
  {"es": "La organización permite trabajar con más libertad.", "ca": "L'organització permet treballar amb més llibertat.", "en": "Organisation lets you work with more freedom.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La gastronomía transmite cultura.", "ca": "La gastronomia transmet cultura.", "en": "Gastronomy passes on culture.", "a": "Eric Ripert", "f": "aportada por GastroGoan"},
  {"es": "El mejor restaurante del mundo no existe.", "ca": "El millor restaurant del món no existeix.", "en": "The best restaurant in the world doesn't exist.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La confianza se construye con la experiencia.", "ca": "La confiança es construeix amb l'experiència.", "en": "Confidence is built through experience.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "Los platos humildes pueden contener una gran historia.", "ca": "Els plats humils poden contenir una gran història.", "en": "Humble dishes can hold a great story.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La cocina de un lugar habla de su historia.", "ca": "La cuina d'un lloc parla de la seva història.", "en": "A place's cooking speaks of its history.", "a": "Marco Pierre White", "f": "aportada por GastroGoan"},
  {"es": "La ejecución importa tanto como la idea.", "ca": "L'execució importa tant com la idea.", "en": "Execution matters as much as the idea.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La educación alimentaria comienza con los niños.", "ca": "L'educació alimentària comença amb els infants.", "en": "Food education starts with children.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La innovación debe responder a una idea y a un propósito.", "ca": "La innovació ha de respondre a una idea i a un propòsit.", "en": "Innovation must answer to an idea and a purpose.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "El objetivo es que el cliente disfrute de la experiencia completa.", "ca": "L'objectiu és que el client gaudeixi de l'experiència completa.", "en": "The goal is for the guest to enjoy the whole experience.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La cocina permite descubrir otras culturas.", "ca": "La cuina permet descobrir altres cultures.", "en": "Cooking lets us discover other cultures.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "La repetición es una parte esencial de la cocina profesional.", "ca": "La repetició és una part essencial de la cuina professional.", "en": "Repetition is an essential part of professional cooking.", "a": "Anthony Bourdain", "f": "aportada por GastroGoan"},
  {"es": "La hospitalidad consiste en hacer que las personas se sientan bienvenidas.", "ca": "L'hospitalitat consisteix a fer que les persones se sentin benvingudes.", "en": "Hospitality is making people feel welcome.", "a": "Danny Meyer", "f": "aportada por GastroGoan"},
  {"es": "La experiencia del equipo influye en el resultado del plato.", "ca": "L'experiència de l'equip influeix en el resultat del plat.", "en": "The team's experience shapes the final dish.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "La cocina es colaboración, no competición.", "ca": "La cuina és col·laboració, no competició.", "en": "Cooking is collaboration, not competition.", "a": "Joan Roca", "f": "aportada por GastroGoan"},
  {"es": "El restaurante no es una iglesia donde se cree o no se cree. La restauración debe seguir siendo un lugar libre y creativo.", "ca": "El restaurant no és una església on es creu o no es creu. La restauració ha de continuar sent un lloc lliure i creatiu.", "en": "A restaurant isn't a church where you either believe or you don't. It must remain a free, creative place.", "a": "Carlo Cracco", "f": "it.wikiquote"},
  {"es": "El éxito debe medirse también por los recuerdos que creas.", "ca": "L'èxit també s'ha de mesurar pels records que crees.", "en": "Success should also be measured by the memories you create.", "a": "Thomas Keller", "f": "aportada por GastroGoan"},
  {"es": "Una historia es más importante que una receta. Una receta puede confundirte; una historia puede inspirarte.", "ca": "Una història és més important que una recepta. Una recepta et pot confondre; una història et pot inspirar.", "en": "A story is more important than a recipe. A recipe can confuse you, but a story can inspire you.", "a": "Marco Pierre White", "f": "Entrevista sobre MasterChef"},
  {"es": "El cocinero es una mezcla de artista y artesano.", "ca": "El cuiner és una barreja d'artista i d'artesà.", "en": "A cook is a mix of artist and craftsman.", "a": "Wolfgang Puck", "f": "aportada por GastroGoan"},
  {"es": "El orden puede hacer más eficiente un negocio gastronómico.", "ca": "L'ordre pot fer més eficient un negoci gastronòmic.", "en": "Order can make a food business more efficient.", "a": "Ferran Adrià", "f": "aportada por GastroGoan"},
  {"es": "La experiencia se construye día tras día.", "ca": "L'experiència es construeix dia rere dia.", "en": "Experience is built day after day.", "a": "Jiro Ono", "f": "aportada por GastroGoan"},
  {"es": "Los ingredientes humildes pueden convertirse en algo extraordinario.", "ca": "Els ingredients humils poden convertir-se en una cosa extraordinària.", "en": "Humble ingredients can become something extraordinary.", "a": "Massimo Bottura", "f": "aportada por GastroGoan"},
  {"es": "La comida está ligada a la memoria y a las emociones.", "ca": "El menjar està lligat a la memòria i a les emocions.", "en": "Food is tied to memory and emotion.", "a": "Eric Ripert", "f": "aportada por GastroGoan"},
  {"es": "Cocinar debería ser una forma de vida, una extensión de uno mismo; nunca un simple trabajo.", "ca": "Cuinar hauria de ser una manera de viure, una extensió d'un mateix; mai una simple feina.", "en": "Cooking should be a way of life — an extension of oneself — never a job.", "a": "Marco Pierre White", "f": "Marco Pierre White in Hell's Kitchen (2008)"}
];
function fraseDelDia(fecha){
  if(!FRASES_DIA.length) return null;
  const d = fecha || new Date();
  const inicio = new Date(d.getFullYear(), 0, 0);
  const dia = Math.floor((d - inicio) / 86400000);   // 1..366
  return FRASES_DIA[(dia - 1) % FRASES_DIA.length];
}
